import json
from datetime import datetime,timezone
import numpy as np,pandas as pd,anndata as ad,h5py
r=PROJECT_ROOT;run=r/'runs/20261106_v7_B_unresolved_review_v1';c=run/'stage_c_QC_views';assert (c/'complete.json').exists();q=pd.read_pickle(run/'stage_b_disjoint_QC_review/adjudication_evidence_PRIVATE.pkl.gz');after=pd.read_pickle(c/'QC_decisions_PRIVATE.pkl.gz');assert q.index.equals(after.index)
old=np.load(r/'runs/20261106_v7_other_unresolved_review_v1/stage_c_QC_views/global_QC_view_v3_masks_PRIVATE.npz');new=np.load(c/'global_QC_view_v4_masks_PRIVATE.npz');pos=q.global_position.to_numpy().astype(int);assert old['primary_keep'][pos].all();want_ex=np.sort(pos[q.QC_operational_exclude_proposed.to_numpy()]);want_hold=np.sort(pos[q.QC_mixed_hematologic_context_holdout.to_numpy()]);assert np.array_equal(want_ex,np.flatnonzero(new['primary_exclude']&~old['primary_exclude'])) and np.array_equal(want_hold,np.flatnonzero(new['QC_holdout']&~old['QC_holdout']));assert not (new['primary_exclude']&new['QC_holdout']).any() and np.array_equal(new['primary_keep'],~new['primary_exclude']&~new['QC_holdout']);assert int(new['primary_exclude'].sum())==int(old['primary_exclude'].sum())+len(want_ex) and int(new['QC_holdout'].sum())==int(old['QC_holdout'].sum())+len(want_hold) and int(new['primary_keep'].sum())==int(old['primary_keep'].sum())-len(want_ex)-len(want_hold)
rows=[]
for name in ['B_unresolved']:
 a=ad.read_h5ad(run/'stage_a_candidates'/name/(name+'_candidate_full_raw.h5ad'));b=ad.read_h5ad(c/name/(name+'_clean_model_raw.h5ad'));t=after.loc[a.obs_names];take=t.current_QC_keep.to_numpy();assert b.obs_names.equals(a.obs_names[take]) and b.obs_names.equals(after.index[after.model_pool.eq(name)&after.current_QC_keep]);assert b.var_names.equals(a.var_names) and b.n_vars==95038;X=a.X[take].tocsr();assert np.array_equal(X.indptr,b.X.indptr) and np.array_equal(X.indices,b.X.indices) and np.array_equal(X.data,b.X.data)
 with h5py.File(c/name/(name+'_clean_model_raw_10x.h5'),'r') as f:
  assert tuple(f['matrix/shape'][:])==(95038,len(b.obs));assert np.array_equal(f['matrix/data'][:],X.data) and np.array_equal(f['matrix/indices'][:],X.indices) and np.array_equal(f['matrix/indptr'][:],X.indptr);assert np.array_equal(f['matrix/barcodes'].asstr()[:],b.obs_names.to_numpy())
 md=pd.read_csv(c/name/(name+'_clean_metadata_PRIVATE.tsv.gz'),sep='\t',index_col='cell_id');assert md.index.equals(b.obs_names);cfg=json.loads((c/name/'refit_config.json').read_text());assert cfg['n_cells']==b.n_obs and cfg['n_genes']==95038 and cfg['globin_excluded_from_model'] is True and cfg['IG_variable_excluded_from_model'] is True
 features=pd.read_csv(c/name/'model_genes.tsv',sep='\t').gene_symbol;assert not features.str.match(r'^(IGLV|IGKV|IGHV)').any() and not features.isin(['HBA1','HBA2','HBB','HBD','HBE1','HBG1','HBG2','HBM','HBQ1','HBZ']).any()
 rows.append({'lineage':name,'n_model':b.n_obs,'n_source':cfg['n_sources'],'n_genes':b.n_vars,'exact_source_raw_count_subset':True,'exact_10x_buffers_and_metadata_axis':True})
out={'status':'PASS','UTC':datetime.now(timezone.utc).isoformat(),'n_new_exclude':len(want_ex),'n_new_holdout':len(want_hold),'n_global_exclude':int(new['primary_exclude'].sum()),'n_global_holdout':int(new['QC_holdout'].sum()),'n_global_keep':int(new['primary_keep'].sum()),'models':rows,'original_QC_v3_exclusions_preserved':True,'no_primary_keep_reentry':True};(c/'independent_input_audit.json').open('x').write(json.dumps(out,indent=2));print(json.dumps(out))
